package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalFrozenConstraints.Proof;
import org.kanger.ContextUniversalSignedUnitRounds.*;
import org.kanger.ContextUniversalSignedUnitRounds.Result;
import org.kanger.ContextUniversalSignedUnitExchange.Exchange;
import org.kanger.ContextWitnessResultTransport.*;

/** Fixed positive application minima must survive every actual synchronous barrier and recheck. */
public final class ContextUniversalSignedApplicationRoundsRunner {
    static final int WORK=64000000;static int checks;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalFrozenBranch.Limits limits(int fact){return new ContextUniversalFrozenBranch.Limits(16,16,fact,512,256,WORK,500000,65536);}
    static Result run(Snapshot x,List<Snapshot> a,Packet p,Map<Cut,PrivatePool> pools,Exchange symbolic,int fact,int rounds){return ContextUniversalSignedUnitRounds.runApplications(x,a,p,pools,symbolic,limits(fact),rounds,WORK);}
    static void incomplete(Result r,String phase,int completed,String why){require(r.status==Status.INCOMPLETE&&r.output==null&&r.symbolicOutput==null&&r.history.isEmpty()&&r.refutations.isEmpty()&&r.phase.equals(phase)&&r.completedRounds==completed,why+": "+r.phase+" "+r.reason);}
    static Result stable(Result r,Exchange initial){require(r.status==Status.STABLE_UNIT_POOLS&&r.output!=null&&r.symbolicOutput!=null&&r.history.size()==r.completedRounds&&r.refutations.isEmpty(),r.phase+" "+r.reason);Packet p=r.input;Exchange e=initial;Map<Cut,PrivatePool> pools=null;for(Round n:r.history){require(n.input==p&&n.symbolicInput==e,"actual shared fixed/symbolic predecessor");for(Cut cut:n.checks.keySet()){org.kanger.ContextUniversalFrozenConstraints.Result c=n.checks.get(cut);require(c.applications&&c.closed&&c.signedUnits&&!c.xRefuted&&!c.foreignRefuted&&c.common==p&&c.exchange==e&&c.pool==n.privateInput.get(cut),"every supplied check uses application mode and exact common/private/symbolic frame");require(n.products.get(cut).bound&&n.products.get(cut).coverage==c&&n.barrier.branches.get(cut).proof==c&&n.symbolicOutput.checks.get(cut)==c,"actual application owner shared by all audits and both outputs");ContextUniversalFrozenConstraints.check(c,16,()->{});}if(pools!=null)for(Cut cut:pools.keySet())require(n.privateInput.get(cut)==pools.get(cut),"actual rebased private continuation");require(n.symbolicOutput.common==n.barrier.packet&&n.symbolicOutput.barrier==n.barrier,"symbolic rebase tied to actual application fixed barrier");p=n.barrier.packet;e=n.symbolicOutput;pools=n.barrier.privatePools;}Round last=r.history.get(r.history.size()-1);require(!last.commonChanged&&!last.symbolicChanged&&!last.privateChanged&&!last.barrier.localChanged,"full proof pools stable before success");return r;}
    static void refuted(Result r,int round,String why){require(r.status==Status.REFUTED&&r.output==null&&r.symbolicOutput==null&&r.history.isEmpty()&&!r.refutations.isEmpty()&&r.completedRounds==round-1,why+": "+r.phase+" "+r.reason);Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Refutation f:r.refutations.values()){require(f.round==round&&!f.proofs.isEmpty(),"actual next-barrier rejection receipts");for(Proof proof:f.proofs){require(proof.clause==null,"genuine empty rejection proof");ContextUniversalSignedApplicationsRunner.audit(proof,seen);}}}
    static Item item(Packet p,String name){return p.items.stream().filter(i->i.atom.predicate.equals(name)).findFirst().get();}
    static void baselineAndGradeOnly()throws Exception {
        Snapshot x=bind(true,"!p(1); !q(1);"),a=bind(false,"!@w p(w)&&q(w)->r(w);");Packet initial=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> targets=Collections.singletonList(a);
        Result legacy=ContextUniversalSignedUnitRounds.run(x,targets,initial,Collections.emptyMap(),null,limits(1),8,WORK);incomplete(legacy,"transfers",0,"legacy binary round refuses application1 at fact bound1");
        Result r=stable(run(x,targets,initial,Collections.emptyMap(),null,1,8),null);require(r.completedRounds==2&&item(r.output.packet,"r").proofs.stream().allMatch(p->p.depth==1&&p.sources.size()==3),"application1 survives self/foreign recheck at fact bound1");
        Result recheck=stable(run(x,targets,r.output.packet,r.output.privatePools,r.symbolicOutput,1,1),r.symbolicOutput);require(recheck.completedRounds==1,"final actual two-channel input stable in one round");
        incomplete(run(x,targets,initial,Collections.emptyMap(),null,1,1),"round-limit",1,"first application proposal cannot return before next-input qualification");incomplete(run(x,targets,initial,Collections.emptyMap(),null,0,8),"transfers",0,"fact bound0 no candidate prefix");
        Result old=ContextUniversalSignedUnitRounds.run(x,targets,initial,Collections.emptyMap(),null,limits(16),8,WORK);require(old.status==Status.STABLE_UNIT_POOLS&&item(old.output.packet,"r").proofs.stream().allMatch(p->p.depth==2),"actual old binary state at grade2");Result improved=stable(run(x,targets,old.output.packet,old.output.privatePools,old.symbolicOutput,16,8),old.symbolicOutput);Round first=improved.history.get(0);require(first.commonChanged&&first.input.items.size()==first.barrier.packet.items.size()&&item(improved.output.packet,"r").proofs.stream().allMatch(p->p.depth==1),"grade-only exact-Source improvement forces another barrier");require(item(old.output.packet,"r").proofs.stream().allMatch(p->p.depth==2),"historical immutable input never relabelled in place");
    }
    static void peersAndChains()throws Exception {
        String rule="!@w p(w)&&q(w)->r(w);";Snapshot x=bind(true,"!p(1); !q(1);"),a=bind(false,rule),b=bind(false,"!~r(1);");Packet initial=ContextPrivateWitnessPoolRunner.common(x);for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){Result r=run(x,order,initial,Collections.emptyMap(),null,1,8);refuted(r,2,"peer negative opinion sees application only at next barrier");Refutation f=r.refutations.get(Cut.of(b));require(f!=null&&f.symbolicIdentity!=null&&!f.inputIdentity.equals(initial.identity)&&f.proofs.stream().anyMatch(p->p.support.depth==2&&p.support.sources.size()==4),"historical application1 remains grade1 in exact empty2/four Sources");}
        Snapshot second=bind(false,"!@w r(w)&&q(w)->s(w);"),negative=bind(false,"!~s(1);");Result chain=run(x,Arrays.asList(a,second,negative),initial,Collections.emptyMap(),null,2,8);refuted(chain,3,"two application barriers then peer contradiction");require(chain.refutations.get(Cut.of(negative)).proofs.stream().anyMatch(p->p.support.depth==3&&p.support.sources.size()==5),"actual max-parent application2 then empty3 with full five Sources");
        Snapshot localNegative=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,b),WORK);Result direct=run(x,Collections.singletonList(localNegative),initial,Collections.emptyMap(),null,1,8);refuted(direct,1,"same-cut application and negative root refute before transfers");require(direct.refutations.get(Cut.of(localNegative)).proofs.stream().anyMatch(p->p.support.depth==2&&p.unit!=null&&(p.unit.producer!=null||p.horn.producer!=null)),"flattened immediate rejection retains real application node");
        Snapshot bad=bind(false,"!bad(1)||other(1);");incomplete(run(x,Arrays.asList(localNegative,bad),initial,Collections.emptyMap(),null,16,8),"checks",0,"later unsupported cut suppresses earlier refutation prefix");
    }
    static void privateAndAlternatives()throws Exception {
        String seed="!$w p(w,1)&&q(w,1);";Snapshot x=bind(true,"!anchor(1); !@w p(w,1)&&q(w,1)->r(w,1);"),a=bind(false,seed),b=bind(false,"!top(1); !@w r(w,1)&&top(1)->s(w,1);");Packet initial=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(initial,x,a,WORK);Map<Cut,PrivatePool> pools=Collections.singletonMap(pool.cut,pool);Result r=stable(run(x,Arrays.asList(a,b),initial,pools,null,2,8),null);Item produced=item(r.output.packet,"s");Source binding=a.primary.get(0).source;require(produced.atom.arguments.get(0).origin.source.equals(binding)&&produced.proofs.stream().allMatch(p->p.depth==2&&p.sources.contains(binding)&&p.sources.size()==4),"private binding preserved through application1, barrier and foreign application2");require(r.output.packet.items.stream().noneMatch(i->i.atom.predicate.equals("p")||i.atom.predicate.equals("q")||i.atom.predicate.equals("top")),"raw independent/private premises stay private");require(pool.common==initial&&pool.local.items.stream().noneMatch(i->i.atom.predicate.equals("r")||i.atom.predicate.equals("s")),"old private pool untouched");Result reverse=stable(run(x,Arrays.asList(b,a),initial,pools,null,2,8),null);require(ContextWitnessResultTransport.sameContents(r.output.packet,reverse.output.packet,WORK),"cut order preserves exact Origin/Source/grade output");
        Snapshot neg=bind(false,"!@w ~r(w,1);");Result collision=run(x,Arrays.asList(a,neg),initial,pools,null,1,8);refuted(collision,2,"private application qualifies independent universal negative next round");require(collision.refutations.get(Cut.of(neg)).proofs.stream().anyMatch(p->p.support.depth==2&&p.support.sources.size()==3&&p.support.sources.contains(binding)),"actual private binding Source retained in rejection");
        Snapshot anchor=bind(true,"!anchor(1);"),privateRules=bind(false,seed+"!@w p(w,1)&&q(w,1)->r(w,1);");Packet cp=ContextPrivateWitnessPoolRunner.common(anchor);PrivatePool only=ContextWitnessResultTransport.privatePool(cp,anchor,privateRules,WORK);Result local=stable(run(anchor,Collections.singletonList(privateRules),cp,Collections.singletonMap(only.cut,only),null,1,8),null);require(local.completedRounds==2&&!local.history.get(0).commonChanged&&local.history.get(0).privateChanged&&local.output.packet.items.size()==1&&item(local.output.privatePools.get(only.cut).local,"r").proofs.stream().allMatch(p->p.depth==1),"private-only application growth prevents common-stable early stop");
        Snapshot sx=bind(true,"!p(1); !q(1);"),producer=bind(false,"!@w p(w)&&q(w)->r(w);"),loop=bind(false,"!@w r(w)->r(w);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(producer,loop),WORK);Packet sp=ContextPrivateWitnessPoolRunner.common(sx);Result alternatives=stable(run(sx,Collections.singletonList(group),sp,Collections.emptyMap(),null,2,8),null);Item out=item(alternatives.output.packet,"r");require(out.proofs.size()==2&&out.proofs.stream().anyMatch(p->p.depth==1&&p.sources.size()==3)&&out.proofs.stream().anyMatch(p->p.depth==2&&p.sources.size()==4),"exact deeper Source superset survives all barriers");incomplete(run(sx,Collections.singletonList(group),sp,Collections.emptyMap(),null,1,8),"transfers",0,"shorter different Source minimum cannot hide deeper alternative");
    }
    static void symbolicAndGuards()throws Exception {
        Snapshot x=bind(true,"!p(1,1); !q(1,1); !@v top(v,1);"),a=bind(false,"!@w p(w,1)&&q(w,1)->r(w,1); !@w @v r(w,1)&&top(v,1)->s(w,v);");Packet cp=ContextPrivateWitnessPoolRunner.common(x);Result r=stable(run(x,Collections.singletonList(a),cp,Collections.emptyMap(),null,2,8),null);require(r.symbolicOutput.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("s")&&u.support.depth==2&&u.owner.applications),"application-backed symbolic unit preserved through rebases/requalification");Snapshot negative=bind(false,"!@w @v ~s(w,v);");Result collision=run(x,Arrays.asList(a,negative),cp,Collections.emptyMap(),null,2,8);refuted(collision,2,"symbolic application-backed result reaches independent negative cut next round");require(collision.refutations.get(Cut.of(negative)).proofs.stream().anyMatch(p->p.support.depth==3&&p.support.sources.size()==6),"imported owner flattened with exact empty3/six Sources");
        incomplete(run(x,Collections.singletonList(a),ContextPrivateWitnessPoolRunner.common(x),Collections.emptyMap(),r.symbolicOutput,16,8),"preflight",0,"equal new Packet cannot substitute actual symbolic rebase basis");
        Result bounded=ContextUniversalSignedUnitRounds.runApplications(x,Collections.singletonList(a),cp,Collections.emptyMap(),null,limits(16),8,1);incomplete(bounded,"preflight",0,"scheduler work refusal not contradiction");
        Map<Cut,Packet> packets=new LinkedHashMap<>();for(Map.Entry<Cut,ConstraintTransfer> e:r.output.branches.entrySet())packets.put(e.getKey(),e.getValue().output);require(ContextWitnessResultTransport.family(r.history.get(r.history.size()-1).input,new ArrayList<>(packets.keySet()),WORK).finish(packets,WORK).status==FamilyStatus.INCOMPLETE,"stable application pools do not issue family STEP/admission");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("signed-application-rounds-").toString());baselineAndGradeOnly();peersAndChains();privateAndAlternatives();symbolicAndGuards();System.out.println("CONTEXT_UNIVERSAL_SIGNED_APPLICATION_ROUNDS_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
